    "count",
    "kg",
    "g",
    "lb",
    "oz",
    "l",
    "ml",
    "gal",
    "qt",
    "pt",
    "cup",
    "tbsp",
    "tsp",
    "pinch",
    "other",
}

UNIT_ALIASES = {
    "": "count",
    "c": "cup",
    "cups": "cup",
    "teaspoon": "tsp",
    "teaspoons": "tsp",
    "tablespoon": "tbsp",
    "tablespoons": "tbsp",
    "gram": "g",
    "grams": "g",
    "kilogram": "kg",
    "kilograms": "kg",
    "liter": "l",
    "liters": "l",
    "milliliter": "ml",
    "milliliters": "ml",
