@dataclass(frozen=True)
class CooklangRecipeData:
    title: str
    description: str
    prep_time_minutes: int | None
    cook_time_minutes: int | None
    servings: int | None
    difficulty: str
    source_url: str
    ingredients: list[CooklangIngredientData]
    steps: list[CooklangStepData]


def parse_cooklang_source(source: str) -> CooklangRecipeData:
    if not source or not source.strip():
        raise ValueError("Cooklang recipe body is required")

