class RecipePhotoSerializer(RequestCacheMixin, serializers.ModelSerializer):
    """Serializer for recipe photos."""

    photo_url = serializers.SerializerMethodField()
    uploaded_by_id = serializers.SerializerMethodField()
    uploaded_by_name = serializers.SerializerMethodField()
    uploaded_by_avatar_url = serializers.SerializerMethodField()

    class Meta:
        model = RecipePhoto
        fields = [
            "id",
            "photo_url",
            "is_primary",
            "caption",
            "order",
            "uploaded_at",
            "uploaded_by_id",
            "uploaded_by_name",
            "uploaded_by_avatar_url",
        ]
        read_only_fields = [
            "id",
            "photo_url",
            "uploaded_at",
            "uploaded_by_id",
            "uploaded_by_name",
            "uploaded_by_avatar_url",
        ]

    def get_photo_url(self, obj):
        """Generate presigned URL for the photo."""
        if not obj.photo_key:
            return None
        try:
            from events.media_services import MediaStorageService

            return MediaStorageService.generate_presigned_url(obj.photo_key)
        except Exception as e:
            logger.error(f"Error generating photo URL for {obj.id}: {e}")
            return None

    def get_uploaded_by_id(self, obj):
        if obj.uploaded_by_id:
            return str(obj.uploaded_by_id)
        return None

    def get_uploaded_by_name(self, obj):
        if not obj.uploaded_by:
            return None
        return obj.uploaded_by.get_full_name() or obj.uploaded_by.username

    def _get_avatar_url(self, user):
        if not user:
            return None

        try:
            import importlib

            social_account_model = importlib.import_module(
                "allauth.socialaccount.models"
            ).SocialAccount
        except Exception:
            social_account_model = None

        try:
            import importlib

            media_storage_service = importlib.import_module(
                "events.media_services"
            ).MediaStorageService
        except Exception:
            media_storage_service = None

        child_profile = getattr(user, "child_profile", None)
        if child_profile:
            profile = child_profile.first()
            if (
                profile
                and profile.profile_picture
                and hasattr(profile.profile_picture, "name")
                and profile.profile_picture.name
                and media_storage_service
            ):
                return media_storage_service.generate_presigned_url(
                    profile.profile_picture.name
                )

        try:
            google_account = user.socialaccount_set.filter(provider="google").first()
            if google_account and "picture" in google_account.extra_data:
                return google_account.extra_data["picture"]
        except Exception:
            if social_account_model is not None:
                pass

        social_account = user.socialaccount_set.first()
        if social_account and "picture" in social_account.extra_data:
            return social_account.extra_data.get(
                "picture", social_account.extra_data.get("avatar_url")
            )

        return None

    def get_uploaded_by_avatar_url(self, obj):
        return self._get_avatar_url(obj.uploaded_by)


class RecipePhotoUploadSerializer(serializers.Serializer):
    """Serializer for uploading recipe photos."""

    photo = serializers.FileField(required=True)
    is_primary = serializers.BooleanField(default=False)
    caption = serializers.CharField(max_length=255, required=False, allow_blank=True)
    create_feed_post = serializers.BooleanField(required=False)

    def validate_photo(self, value):
        """Validate the uploaded file is an image."""
        from .services import RecipePhotoService

        allowed_types = [
            "image/jpeg",
            "image/png",
            "image/gif",
            "image/webp",
            "image/heic",
            "image/heif",
        ]
        if value.content_type not in allowed_types:
            raise serializers.ValidationError(
                f"Invalid file type. Allowed types: {', '.join(allowed_types)}"
            )
        max_size = RecipePhotoService.MAX_FILE_SIZE
        if value.size > max_size:
            raise serializers.ValidationError(
                f"File size must be less than {max_size // (1024 * 1024)}MB"
            )
        return value


