from django.core.management.base import BaseCommand

from recipes.cooklang import render_cooklang_source
from recipes.models import Recipe


class Command(BaseCommand):
    help = "Generate Cooklang source for recipes that do not have it yet."

    def add_arguments(self, parser):
        parser.add_argument("--recipe-id", dest="recipe_id")
        parser.add_argument("--overwrite", action="store_true")

    def handle(self, *args, **options):
        queryset = Recipe.objects.prefetch_related("ingredients", "steps")
        if options["recipe_id"]:
            queryset = queryset.filter(id=options["recipe_id"])
        if not options["overwrite"]:
            queryset = queryset.filter(cooklang_source="")

        updated = 0
        # chunk_size required for prefetch_related to apply with iterator()
        for recipe in queryset.iterator(chunk_size=500):
            recipe.cooklang_source = render_cooklang_source(
                title=recipe.title,
                description=recipe.description,
                servings=recipe.servings,
                prep_time_minutes=recipe.prep_time_minutes,
                cook_time_minutes=recipe.cook_time_minutes,
                difficulty=recipe.difficulty,
                source_url=recipe.source_url,
                ingredients=[
                    {
                        "name": ingredient.name,
                        "amount": ingredient.amount,
                        "unit": ingredient.unit,
                        "notes": ingredient.notes,
                    }
                    for ingredient in recipe.ingredients.all()
                ],
                steps=[
                    {
                        "instruction": step.instruction,
                        "timer_minutes": step.timer_minutes,
                    }
                    for step in recipe.steps.all()
                ],
            )
            recipe.cooklang_parse_status = "VALID"
            recipe.cooklang_parse_error = ""
            recipe.save(
                update_fields=[
                    "cooklang_source",
                    "cooklang_parse_status",
                    "cooklang_parse_error",
                    "updated_at",
                ]
            )
            updated += 1

        self.stdout.write(self.style.SUCCESS(f"Backfilled {updated} recipes"))

