from __future__ import annotations

import re
from dataclasses import asdict, dataclass
from decimal import Decimal, InvalidOperation
from typing import Any

from cooklang_py import Recipe as CooklangRecipe

from .models import Recipe, RecipeIngredient

CLANCAL_UNITS = {choice[0] for choice in RecipeIngredient.UNIT_CHOICES}
VALID_DIFFICULTIES = {choice[0] for choice in Recipe.DIFFICULTY_CHOICES}

UNIT_ALIASES = {
    "": "count",
    "c": "cup",
    "cups": "cup",
    "teaspoon": "tsp",
    "teaspoons": "tsp",
    "tablespoon": "tbsp",
    "tablespoons": "tbsp",
    "gram": "g",
    "grams": "g",
    "kilogram": "kg",
    "kilograms": "kg",
    "liter": "l",
    "liters": "l",
    "milliliter": "ml",
    "milliliters": "ml",
    "ounce": "oz",
    "ounces": "oz",
    "pound": "lb",
    "pounds": "lb",
}


@dataclass(frozen=True)
class CooklangIngredientData:
    name: str
    amount: Decimal | None
    unit: str
    notes: str
    order: int

    def to_dict(self) -> dict[str, Any]:
        data = asdict(self)
        if self.amount is not None:
            data["amount"] = str(self.amount)
        return data


@dataclass(frozen=True)
class CooklangStepData:
    instruction: str
    timer_minutes: int | None
    order: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True)
class CooklangRecipeData:
    title: str
    description: str
    prep_time_minutes: int | None
    cook_time_minutes: int | None
    servings: int | None
    difficulty: str
    source_url: str
    ingredients: list[CooklangIngredientData]
    steps: list[CooklangStepData]


def parse_cooklang_source(source: str) -> CooklangRecipeData:
    if not source or not source.strip():
        raise ValueError("Cooklang recipe body is required")

    try:
        parsed = CooklangRecipe(source)
    except ValueError as exc:
        raise ValueError(f"Invalid Cooklang source: {exc}") from exc

    ingredients = [
        CooklangIngredientData(
            name=ingredient.name,
            amount=_decimal_amount(getattr(ingredient.quantity, "amount", None)),
            unit=_normalize_unit(getattr(ingredient.quantity, "unit", "")),
            notes=ingredient.notes or "",
            order=index,
        )
        for index, ingredient in enumerate(parsed.ingredients)
    ]
    steps = [
        CooklangStepData(
            instruction=_render_step_instruction(step),
            timer_minutes=_first_timer_minutes(step),
            order=index,
        )
        for index, step in enumerate(parsed.steps)
    ]

    metadata = parsed.metadata
    return CooklangRecipeData(
        title=str(metadata.get("title", "") or ""),
        description=str(metadata.get("description", "") or ""),
        prep_time_minutes=_minutes(
            metadata.get("time.prep") or metadata.get("prep time")
        ),
        cook_time_minutes=_minutes(
            metadata.get("time.cook") or metadata.get("cook time")
        ),
        servings=_integer(metadata.get("servings") or metadata.get("yield")),
        difficulty=_difficulty(metadata.get("difficulty")),
        source_url=str(metadata.get("source.url", "") or ""),
        ingredients=ingredients,
        steps=steps,
    )


def render_cooklang_source(
    *,
    title: str,
    description: str,
    servings: int | None,
    prep_time_minutes: int | None,
    cook_time_minutes: int | None,
    difficulty: str,
    source_url: str,
    ingredients: list[dict[str, Any]],
    steps: list[dict[str, Any]],
) -> str:
    metadata_lines = ["---", f"title: {_metadata_value(title)}"]
    if description:
        metadata_lines.append(f"description: {_metadata_value(description)}")
    if servings:
        metadata_lines.append(f"servings: {servings}")
    if prep_time_minutes:
        metadata_lines.append(f"time.prep: {prep_time_minutes} minutes")
    if cook_time_minutes:
        metadata_lines.append(f"time.cook: {cook_time_minutes} minutes")
    if difficulty:
        metadata_lines.append(f"difficulty: {difficulty.lower()}")
    if source_url:
        metadata_lines.append(f"source.url: {source_url}")
    metadata_lines.append("---")

    ingredient_line = " ".join(_format_ingredient(item) for item in ingredients)
    body_parts = [ingredient_line] if ingredient_line else []
    body_parts.extend(_format_step(step) for step in steps)
    return "\n".join(metadata_lines) + "\n\n" + "\n\n".join(body_parts).strip() + "\n"


def _render_step_instruction(step) -> str:
    rendered_parts = []
    for item in step:
        item_type = item.__class__.__name__
        if item_type in {"Ingredient", "Cookware"}:
            rendered_parts.append(item.name)
        elif item_type != "Timing":
            rendered_parts.append(str(item))

    rendered = "".join(rendered_parts).replace("\\", "")
    rendered = re.sub(r"\s+(for|about|around)\s*([.!?,;:])", r"\2", rendered)
    rendered = re.sub(r"\b(for|about|around)\s*$", "", rendered)
    rendered = re.sub(r"\s+([,.!?;:])", r"\1", rendered)
    return re.sub(r"\s+", " ", rendered).strip()


def _first_timer_minutes(step) -> int | None:
    timers = [part for part in step if part.__class__.__name__ == "Timing"]
    if not timers:
        return None
    quantity = timers[0].quantity
    amount = _decimal_amount(getattr(quantity, "amount", None))
    unit = str(getattr(quantity, "unit", "") or "").lower()
    if amount is None:
        return None
    multiplier = 60 if unit in {"h", "hour", "hours"} else 1
    return int(amount * multiplier)


def _decimal_amount(value: Any) -> Decimal | None:
    if value in (None, ""):
        return None
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return None


def _normalize_unit(raw_unit: Any) -> str:
    raw_text = str(raw_unit or "").strip().lower()
    normalized = UNIT_ALIASES.get(raw_text, raw_text)
    return normalized if normalized in CLANCAL_UNITS else "other"


def _minutes(value: Any) -> int | None:
    if value in (None, ""):
        return None
    text = str(value).strip().lower()
    h_match = re.search(r"(\d+)\s*h", text)
    m_match = re.search(r"(\d+)\s*m", text)
    if h_match or m_match:
        hours = int(h_match.group(1)) * 60 if h_match else 0
        minutes = int(m_match.group(1)) if m_match else 0
        return hours + minutes
    number_match = re.search(r"\d+", text)
    return int(number_match.group(0)) if number_match else None


def _integer(value: Any) -> int | None:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _difficulty(value: Any) -> str:
    normalized = str(value or "MEDIUM").strip().upper()
    return normalized if normalized in VALID_DIFFICULTIES else "MEDIUM"


def _format_ingredient(item: dict[str, Any]) -> str:
    name = str(item["name"]).strip()
    amount = item.get("amount")
    unit = item.get("unit") or "count"
    notes = item.get("notes") or ""
    quantity = ""
    if amount not in (None, ""):
        amount_text = _format_decimal(amount)
        quantity = (
            f"{{{amount_text}}}" if unit == "count" else f"{{{amount_text}%{unit}}}"
        )
    note_text = f"({notes})" if notes else ""
    return f"@{name}{quantity}{note_text}"


def _format_step(step: dict[str, Any]) -> str:
    instruction = str(step["instruction"]).strip().replace("\n", "\\\n")
    timer = step.get("timer_minutes")
    if timer:
        return f"{instruction} ~{{{timer}%minutes}}"
    return instruction


def _format_decimal(value: Any) -> str:
    if isinstance(value, Decimal):
        return format(value.normalize(), "f")
    return str(value)


def _metadata_value(value: str) -> str:
    return str(value).replace("\n", " ").strip()

